number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;2&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;6&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;10&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;14&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;	&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		P1=&lt;span class=&#34;number&#34;&gt;0xFF&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		P11=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P17==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P17==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;3&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;7&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;11&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;15&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;	&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		P1=&lt;span class=&#34;number&#34;&gt;0xFF&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		P10=&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P17==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P17==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;4&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P16==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;8&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P15==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;12&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;		&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&amp;#123;Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);&lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(P14==&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;);Delay(&lt;span class=&#34;number&#34;&gt;20&lt;/span&gt;);num=&lt;span class=&#34;number&#34;&gt;16&lt;/span&gt;;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;  &lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;type&#34;&gt;void&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;display&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    P2 = s[num];&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;type&#34;&gt;void&lt;/span&gt; &lt;span class=&#34;title function_&#34;&gt;main&lt;/span&gt;&lt;span class=&#34;params&#34;&gt;()&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;while&lt;/span&gt;(&lt;span class=&#34;number&#34;&gt;1&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#123;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        key_scan();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;        display();&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&amp;#125;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;

&lt;p&gt;&lt;img src=&#34;/images/BlogImg/202305081916666.png&#34; class=&#34;lazyload&#34; data-srcset=&#34;/images/BlogImg/202305081916666.png&#34; srcset=&#34;data:image/gif;base64,R0lGODlhAQABAIAAAP///////yH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==&#34;&gt;&lt;/p&gt;
&lt;/div&gt;&lt;div class=&#34;story post-story&#34;&gt;&lt;h2 id=&#34;定时器&#34;&gt;定时器&lt;/h2&gt;&lt;h3 id=&#34;工作方式&#34;&gt;工作方式&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;interrupt0，13位，当 INT0 引脚由高电平变为低电平时触发中断。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;$X&amp;#x3D;8192-N\frac{12}{fosc}$&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;上次计数为0，要重复计数需要置零&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;interrupt1，16位，当定时器 0 计数器溢出时触发中断。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;$X&amp;#x3D;65536-N\frac{12}{fosc}$&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;上次计数值为0，要重复计数需要重置初值&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;interrupt2，8位自动重置定时&amp;#x2F;计数器，当 INT1引脚由高电平变为低电平时触发中断。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;interrupt3，8位，只有T0才能使用，当定时器 1 计数器溢出时触发中断。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;$X&amp;#x3D;256-N\frac{12}{fosc}$&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;计数器自动配置初值，不需要用户重置&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;interrupt4，串口中断，当串口接收完成（RI）或发送完成（TI）时触发中断。&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;TMOD-寄存器&#34;&gt;TMOD 寄存器&lt;/h3&gt;&lt;p&gt;TMOD 的低 4 位控制定时器 0，高 4 位控制定时器 1，每个定时器都有两个工作模式可以选择&lt;/p&gt;
&lt;p&gt;M0表示定时器0，M1表示定时器1&lt;/p&gt;
&lt;p&gt;TMOD&amp;#x3D;0x20表示定时器1设置为2模式&lt;/p&gt;
&lt;p&gt;TMOD&amp;#x3D;0x02表示定时器0设置为2模式&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;TMOD&lt;/th&gt;
&lt;th&gt;GATE&lt;/th&gt;
&lt;th&gt;C&amp;#x2F;T&lt;/th&gt;
&lt;th&gt;M1&lt;/th&gt;
&lt;th&gt;M0&lt;/th&gt;
&lt;th&gt;工作模式&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;&lt;tr&gt;
&lt;td&gt;0x00&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;模式 0：13 位计数器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x01&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;模式 1：16 位计数器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x02&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;模式 2：8 位自动重装载计数器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x03&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;模式 3：16 位自动重装载计数器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x04&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;模式 4：外部事件计数&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x05&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;模式 5：保留&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x06&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;模式 6：8 位 PWM 波形发生器&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;0x07&lt;/td&gt;
&lt;td&gt;0&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;1&lt;/td&gt;
&lt;td&gt;模式 7：16 位 PWM 波形发生器&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;&lt;/table&gt;
&lt;h3 id=&#34;TH和TL寄存器&#34;&gt;TH和TL寄存器&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;code&gt;TH0/TL0&lt;/code&gt;表示定时器0的高低八位&lt;/li&gt;
&lt;li&gt;&lt;code&gt;TH1/TL1&lt;/code&gt;表示定时器1的高低八位&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;IT寄存器&#34;&gt;IT寄存器&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;IT0&lt;/code&gt;，外部中断寄存器&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;IT1&lt;/code&gt;，外部中断寄存器&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;IT0/IT1=0&lt;/code&gt;，低电平触发&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;&lt;p&gt;&lt;code&gt;IT0/IT1=1&lt;/code&gt;，下降沿触发&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;中断寄存器&#34;&gt;中断寄存器&lt;/h3&gt;&lt;ol&gt;
&lt;li&gt;&lt;code&gt;ET0/ET1&lt;/code&gt;，定时器中断使能寄存器，为1中断允许，为0不允许&lt;/li&gt;
&lt;li&gt;&lt;code&gt;EA&lt;/code&gt;，总中断使能寄存器，为1中断允许，为0不允许&lt;/li&gt;
&lt;li&gt;&lt;code&gt;TR0/TR1&lt;/code&gt;，定时器启动控制寄存器，为1时开始计数，为0时停止计数。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;strong&gt;12MHz晶振对应的一个机器周期为1us，需要延时50ms，则从65536-50000开始计数，分为高低八位分别存储计数，当定时器0计数到65536溢出位时，触发timer_isr中断，执行函数。&lt;/strong&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;figure class=&#34;highlight c&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;gutter&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;1&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;2&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;3&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;4&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;5&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;6&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;7&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;8&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;9&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;10&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;11&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;12&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;13&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;14&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;15&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;16&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;17&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;18&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;19&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;20&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;21&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;22&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;23&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;24&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;25&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;26&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;27&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;28&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;29&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;30&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;31&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;32&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;33&lt;/span